s":[],"transform":{"position":[1.75,0,3.75],"rotation":[0,0,0],"scale":[2,2,1]},"imageAssetId":"5b3c8959-da4d-4647-8568-39f236ec5f6b","billboard":"none","collision":{"solid":false,"radius":0.25},"initialState":{},"visibleWhen":null,"interaction":{"scriptId":null,"itemDefinitionId":null,"canTake":false,"reach":2,"audioAssetId":null,"showsTime":false,"condition":null,"unavailableReason":"","itemUseReason":"Эта вещь здесь не подходит."},"container":null,"transition":null},{"id":"object-ee18bc39-0491-48ed-879d-876040238080","name":"Окно2","light":{"enabled":true,"color":"#786c59","intensity":25,"distance":5,"offset":[0,0.5,0],"portable":true,"condition":null},"spatialAudio":{"enabled":true,"assetId":"b897f418-00d7-43fd-a42e-70ebd2074197","volume":0.3,"loop":true,"near":0.5,"far":3,"offset":[0,1,0],"portable":true,"condition":null},"locationId":"location-94bfe196-935b-4cab-8777-bcdcd7aedeb6","kind":"prop","notes":"","tags":[],"transform":{"position":[0.15,0.75,2],"rotation":[0,1.5707963267948966,0],"scale":[1.5,1.5,1]},"imageAssetId":"ef7cfb44-da33-4761-a2af-8d8a91e212a8","billboard":"none","collision":{"solid":false,"radius":0.25},"initialState":{},"visibleWhen":null,"interaction":{"scriptId":"script-6460a394-fdad-4ac5-95d8-7ed23aa19bab","itemDefinitionId":null,"canTake":false,"reach":2,"audioAssetId":null,"showsTime":false,"condition":null,"unavailableReason":"","itemUseReason":"Эта вещь здесь не подходит."},"container":null,"transition":null},{"id":"object-4e4fad94-a221-410f-9cb2-a0cd4328e8e7","name":"Лестница вниз","locationId":"location-94bfe196-935b-4cab-8777-bcdcd7aedeb6","kind":"exit","notes":"","tags":[],"transform":{"position":[11.5,-0.5,3],"rotation":[0,1.5707963267948966,0],"scale":[2.5,2.5,1]},"imageAssetId":"80b456b7-ba9d-4f73-a2c1-c562f6375e68","billboard":"none","collision":{"solid":false,"radius":0.25},"initialState":{},"visibleWhen":null,"interaction":{"scriptId":null,"itemDefinitionId":null,"canTake":false,"reach":2,"audioAssetId":null,"showsTime":false,"condition":null,"unavailableReason":"","itemUseReason":"Эта вещь здесь не подходит."},"container":null,"transition":null},{"id":"object-c03958ae-d7a8-4a93-9897-ca2761081563","name":"Окно3","light":{"enabled":false,"color":"#786c59","intensity":25,"distance":5,"offset":[0,0.5,0],"portable":true,"condition":null},"spatialAudio":{"enabled":true,"assetId":"c527d3e1-a3b7-4a63-8f76-1d6b335cebc0","volume":1,"loop":true,"near":1,"far":3,"offset":[0,1,0],"portable":true,"condition":null},"locationId":"location-94bfe196-935b-4cab-8777-bcdcd7aedeb6","kind":"prop","notes":"","tags":[],"transform":{"position":[0.15,0.75,2.5],"rotation":[0,1.5707963267948966,0],"scale":[1.5,1.5,1]},"imageAssetId":"ef7cfb44-da33-4761-a2af-8d8a91e212a8","billboard":"none","collision":{"solid":false,"radius":0.25},"initialState":{},"visibleWhen":null,"interaction":{"scriptId":null,"itemDefinitionId":null,"canTake":false,"reach":2,"audioAssetId":null,"showsTime":false,"condition":null,"unavailableReason":"","itemUseReason":"Эта вещь здесь не подходит."},"container":null,"transition":null}],"items":[{"id":"item-915eaca4-c097-4d48-8f0f-00e6afb1ef64","name":"Рубашка","description":"Помятая рубашка. В ней вы выглядите подозрительно презентабельно. (+РАЗУМ) (+Убер-Эго)","tags":[],"imageAssetId":"ff8f6f5b-718c-45f7-9859-7fc47afb5506","showsTime":false,"equipmentSlot":"torso","capacityBonus":0,"modifiers":{"skill-d8d2f316-1478-4bf7-aba1-6b1dce769113":1,"stat-8cab4fe6-418f-468a-b4fb-c9e11ed9a2e7":1}},{"id":"item-fdc50566-3454-4c4a-8219-c0991482e090","name":"Разбитая бутылка","description":"Разбитая бутылка. Больше не применима к хранению жидкости.","tags":["мусор"],"imageAssetId":"3fd1b62d-bb9e-4354-ad86-f3b87ceacd3a","showsTime":false,"equipmentSlot":null,"capacityBonus":0,"modifiers":{}},{"id":"item-af8ec41a-39d8-4d28-891f-f5bd9e2b5607","name":"Мятая Бумага","description":"Комок мятой бумаги. Когда-то была использована и выброшена.","tags":["мусор"],"imageAssetId":"cad3fa92-59ce-45ae-967e-4e2517d3c7b9","showsTime":false,"equipmentSlot":null,"capacityBonus":0,"modifiers":{}},{"id":"item-17194795-3c51-414d-ad11-ae462cf49414","name":"Пустая Бутылка","description":"Пустая бутылка. На этикетке написано «Caleste»","tags":["мусор"],"imageAssetId":"77125a25-b788-4adf-90a7-cea5d4b9257c","showsTime":false,"equipmentSlot":null,"capacityBonus":0,"modifiers":{}},{"id":"item-550f8635-7df8-41ee-a45d-0f2c4a29ce3e","name":"Читательский билет","description":"Небольшая книжечка в тонкой кожаной обертке, которая указывает на то, что вы являетесь студентом Супербианского Университета. Она позволяет свободно брать книги из местной библиотеки.","tags":[],"imageAssetId":"6e18cee8-ed64-4efa-bc49-50cfbd041729","showsTime":false,"equipmentSlot":null,"capacityBonus":0,"modifiers":{}},{"id":"item-6f5a3fe6-4a08-4eaa-8c78-1dbc3a345b69","name":"Ключ","description":"Домашний ключ. По всей видимости, от вашей квартиры. Зубцы кажутся такими острыми, будто они готовы откусить от вас кусок.","tags":[],"imageAssetId":"3adafbdb-6aab-413c-a831-8fdf70e6716c","showsTime":false,"equipmentSlot":null,"capacityBonus":0,"modifiers":{}},{"id":"item-40c7857d-575a-445d-9bc0-23e6a8cd8807","name":"Карманные часы","description":"Странные карманные часы. Холодная, тяжелая латунь упрямо тянет вашу ладонь вниз. Кажется, от этой тяжести само время течет по другому...","tags":[],"imageAssetId":"94f69584-7ba0-4496-b564-d218a5a16377","showsTime":true,"equipmentSlot":null,"capacityBonus":0,"modifiers":{}},{"id":"item-c6574c1b-92b2-4efe-86f8-99c70f73a04a","name":"Портфель","description":"","tags":[],"imageAssetId":null,"showsTime":false,"equipmentSlot":"accessory","capacityBonus":3,"modifiers":{"skill-d8d2f316-1478-4bf7-aba1-6b1dce769113":1}},{"id":"item-5c5675cf-67aa-48dc-9faa-b91c1256a7b2","name":"Визитка","description":"Визитка некоего аптекаря, который разместил свой бизнес на проспекте святого Паисия, дом 13. Также указан номер телеграфа по адресу Гарро-Вия, дом 26.","tags":[],"imageAssetId":"4e104fad-8f47-4cec-8ff8-af0762cc552c","showsTime":false,"equipmentSlot":null,"capacityBonus":0,"modifiers":{}},{"id":"item-8c5b2546-3951-433a-98dc-bb894b813916","name":"Баночка «Параколума»","description":"Небольшая медицинская баночка, с таблетками параколума внутри. Параколум - опиоидный препарат обезболивающего действия.","tags":[],"imageAssetId":"e36b1e79-48eb-4167-9289-e8e44b662da5","showsTime":false,"equipmentSlot":null,"capacityBonus":0,"modifiers":{}},{"id":"item-3416acf1-e873-4b72-8bc5-fb0e023e408a","name":"Брюки","description":"Довольно широкие брюки. В них достаточно просторно, чтобы пронести две бутылки вина.","tags":[],"imageAssetId":"489d2698-980a-4167-9725-2a893ea00fcd","showsTime":false,"equipmentSlot":"legs","capacityBonus":1,"modifiers":{}},{"id":"item-502588f0-d866-4f80-a255-26c627390e71","name":"Туфли","description":"Обычные удобные туфли. Защитят ваши стопы от асфальта.","tags":[],"imageAssetId":"d212d6be-aebb-44d6-8d2b-ad4bc8c52f37","showsTime":false,"equipmentSlot":"feet","capacityBonus":0,"modifiers":{}},{"id":"item-1f75c10a-d40d-4b65-9d95-52c615cc3551","name":"Мука","description":"Небольшой мешочек муки.","tags":["ингридиент"],"imageAssetId":null,"showsTime":false,"equipmentSlot":null,"capacityBonus":0,"modifiers":{}},{"id":"item-0c04e031-50bb-4b97-80fd-576e54c07791","name":"Вода","description":"Небольшой бурдюк с водой.","tags":["ингридиент"],"imageAssetId":null,"showsTime":false,"equipmentSlot":null,"capacityBonus":0,"modifiers":{}},{"id":"item-73da8a53-1e15-4330-9afb-0b02ad62787b","name":"Хлеб","description":"Кусочек хлеба","tags":[],"imageAssetId":null,"showsTime":false,"equipmentSlot":null,"capacityBonus":0,"modifiers":{}}],"character":{"name":"...","stats":[{"id":"stat-8cab4fe6-418f-468a-b4fb-c9e11ed9a2e7","name":"РАЗУМ","initial":1,"min":0,"max":10,"description":"Ваш РАЗУМ. Нематериальное, эмпирическое, эмоциональное. Стремится к знаниям, самосовершенствованию, познанию мира.","barAssets":{"frameAssetId":null,"fillAssetId":null}},{"id":"stat-0fdce2d6-7757-4491-a081-1ac15c5ee9fc","name":"МАТЕРИЯ","initial":1,"min":0,"max":10,"description":"Ваша МАТЕРИЯ. Она физическая, механистическая, осознает мир через материальные органы чувств."},{"id":"stat-8eb3a002-252d-41c3-8b82-7eda776dbbc3","name":"ПОТЕНЦИЯ","initial":1,"min":0,"max":10,"description":"Ваша ПОТЕНЦИЯ. Ваша способность к осуществлению замыслов. Материальная и мыслительная готовность к реализации действий."}],"skills":[{"id":"skill-bfb72caf-6fe4-4457-a5b8-03b594a7b1af","name":"«Оно»","initial":1,"min":0,"max":10,"description":"Нечто глубинное, не поддающееся объяснению, заложенное в самой варварской глубине человеческого самосознания. Подчиняется только законам природы, потакая инстинктам.","imageAssetId":"5c06595a-f745-4d2b-9ec0-ceeff2d007e5","imageVariants":[]},{"id":"skill-3bb54cd9-0db5-4243-871d-37b504d7523b","name":"«Эго»","initial":1,"min":0,"max":10,"description":"Это Вы. То, как вы понимаете собственное Я. Оно получает информацию, воспринимает мир, других людей, поглощает идеи. ","imageAssetId":"56077692-f208-4927-9dcd-02161a73ad84"},{"id":"skill-d8d2f316-1478-4bf7-aba1-6b1dce769113","name":"«Убер-Эго»","initial":1,"min":0,"max":10,"description":"То, что стоит выше вас. Мораль. Закон. Слово божье. То, что управляет вами. То, к чему вы стремитесь. Оно рациональное, твердое, подчиненное логике. ","imageAssetId":"32e9c875-6d43-4f81-8d07-53c017a8ae32"}],"statuses":[{"id":"status-dd5589a2-139f-43b1-8e2e-634dfb01edd2","name":"Юноша","description":"Вы Юноша. Общество относится к вам соответственно.","initiallyActive":false,"modifiers":{}},{"id":"status-e8b2a38e-a7fb-4442-b1ad-7dac4214938b","name":"Девушка","description":"Вы Девушка. Общество относится к вам соответственно.","initiallyActive":false,"modifiers":{}}]},"flags":{"awakened":false,"stul_N":null,"read":null,"good_looking":false,"bad_looking":false,"pp":true,"up_icon":false,"gone_icon":false,"naked":false},"scripts":[{"id":"script-0ca99cfc-4880-4b6a-9856-f8fd6c09e31b","name":"Увертюра","entryNodeId":"node-48fb3762-795a-474a-946e-4c0436f6f284","nodes":[{"id":"node-48fb3762-795a-474a-946e-4c0436f6f284","paragraphs":[{"spans":[{"text":"...","marks":[]}],"audioAssetId":"38cecc81-cc15-40aa-b1d5-8323d8dc6327","audioLoop":false,"audioVolume":0.5},{"spans":[{"text":"Твоя голова пуста. В ней нет мыслей. Нет ничего. Только тьма. И этот завывающий звук ветра, некогда гонявший мысли внутри твоего черепа. Но даже он исчерпал свой энтузиазм. Его силы едва хватает, чтобы создать этот звук...","marks":["italic"]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"Тут нет ничего. Ты оказался в точке конца всего сущего. Или, по крайней мере, приблизился к ней.","marks":["italic"]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"Нирвана. Ты освобожден от своих переживаний и мыслей. Они не тяготят тебя. Но ты не ощущаешь... ничего. Ты чувствуешь.","marks":["italic"]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"Отдых.","marks":["italic"]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-04a6289b-0cd9-444c-8f82-40f69be5322a","label":"Да... тут так спокойно.","nextNodeId":"node-e40d3f55-4a19-4263-be2d-ef713c41f933","condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]},{"id":"choice-5c864182-172c-47d7-bc5d-69f07462b746","label":"Мне не нужен отдых. Я полон сил.","nextNodeId":"node-b33398af-984c-4a1c-85d0-ab51d3d66831","condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-e40d3f55-4a19-4263-be2d-ef713c41f933","paragraphs":[{"spans":[{"text":"В этом и кроется проблема. Ты не ","marks":["italic"]},{"text":"нигде, ","marks":["bold","italic"]},{"text":"это иллюзия спокойствия. Тем не менее тут довольно приятно. Голова пустует, в ней гуляет ветер, рискующий превратиться в ураган.","marks":["italic"]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"Здесь нет никаких раздражителей. Будто весь организм наконец перестал анализировать. Внутренний диалог схлопнулся и умолк.","marks":["italic"]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"Тут нет ничего. И нет никого. Тут нет всего того, что так тяготило тебя. Нет бесконечно бегущей вперед стрелки времени, угрюмо указывающей тебе на то, чего ты не успел.","marks":["italic"]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"Нет здесь, впрочем, и того, что когда-то держало тебя по ту сторону бытия. ","marks":["italic"]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-6d64c6b4-a3f1-4e68-8e6b-e2e959aec488","label":"Я всегда держался сам.","nextNodeId":"node-5a163e06-7a04-4634-82f2-7bea5b2db15d","condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[{"type":"changeTrait","kind":"skill","traitId":"skill-3bb54cd9-0db5-4243-871d-37b504d7523b","mode":"add","value":1}]},{"id":"choice-d4e9bcec-bba5-4b44-966c-ec0958bccee9","label":"Мне всегда кто-то помогал.","nextNodeId":"node-5f156ce8-97c5-4eeb-832d-adea0eba5a2b","condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[{"type":"changeTrait","kind":"skill","traitId":"skill-d8d2f316-1478-4bf7-aba1-6b1dce769113","mode":"add","value":1}]},{"id":"choice-d122864e-6e3d-4a17-8505-78d548024e99","label":"Зачем я держался?","nextNodeId":"node-b29147f0-45ff-4ea8-b3d6-60bdd091b361","condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[{"type":"changeTrait","kind":"skill","traitId":"skill-bfb72caf-6fe4-4457-a5b8-03b594a7b1af","mode":"add","value":1}]}]},{"id":"node-5a163e06-7a04-4634-82f2-7bea5b2db15d","paragraphs":[{"spans":[{"text":"ЭГО: ","marks":["bold"]},{"text":"Где-то внутри разливается странное тепло. Сначала оно где-то на кончиках пальцев... потом в районе запястья...","marks":["italic"]}],"audioAssetId":null,"voiceId":"ego","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"ЭГО:","marks":["bold"]},{"text":" ","marks":[]},{"text":"Ты что-то помнишь. Совсем недавно тебе было совершенно хорошо и понятно, кто ты и где ты.","marks":["italic"]}],"audioAssetId":null,"voiceId":"ego","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"ЭГО: ","marks":["bold"]},{"text":"А потом куда-то это пропало. И ты оказался в петле.","marks":["italic"]}],"audioAssetId":null,"voiceId":"ego","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"ЭГО: ","marks":["bold"]},{"text":"С тех пор тебе больно.","marks":["italic"]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-59b3cf2d-199c-4528-a17d-3534fa204fc4","label":"Почему мне больно?","nextNodeId":"node-58088993-ed89-4147-9508-a4231e6cf455","condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-58088993-ed89-4147-9508-a4231e6cf455","paragraphs":[{"spans":[{"text":"ЭГО: ","marks":["bold"]},{"text":"РАЗУМ ","marks":["bold","italic"]},{"text":"защитил нас от этого знания.","marks":["italic"]}],"audioAssetId":null,"voiceId":"ego","audioLoop":false,"audioVolume":1,"audioStop":false}],"choices":[{"id":"choice-fe7058e2-fd6d-49b0-9f96-140bef16a83b","label":"Закончить","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-0725a041-845a-455b-bc90-27290e86f885","paragraphs":[{"spans":[{"text":"ОНО: ","marks":["bold"]},{"text":"Люди.","marks":["italic"]}],"audioAssetId":null,"voiceId":"ono","audioLoop":false,"audioVolume":1,"audioStop":false}],"choices":[{"id":"choice-ae52e396-5a31-4723-89dc-71f3fecfbdc1","label":"Закончить","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-b29147f0-45ff-4ea8-b3d6-60bdd091b361","paragraphs":[{"spans":[{"text":"ОНО: ","marks":["bold"]},{"text":"Реальный мир неприятен.","marks":["italic"]}],"audioAssetId":null,"voiceId":"ono","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"ОНО: ","marks":["bold"]},{"text":"Вечно кому-то что-то нужно. Вечно правила. Нельзя то. Не делай этого. Прекрати. Это неприлично.","marks":["italic"]}],"audioAssetId":null,"voiceId":"ono","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"ОНО: ","marks":["bold"]},{"text":"Тут нет правил. Никто не осудит тебя. Все именно так, как должно быть. Мы свободны делать то, что мы хотим. ","marks":["italic"]}],"audioAssetId":null,"voiceId":"ono","audioLoop":false,"audioVolume":1,"audioStop":false}],"choices":[{"id":"choice-d07e5e38-f8a6-4dbf-9d19-d3f4fdda4cb6","label":"Почему мы не можем делать этого в реальной жизни?","nextNodeId":"node-0725a041-845a-455b-bc90-27290e86f885","condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-5f156ce8-97c5-4eeb-832d-adea0eba5a2b","paragraphs":[{"spans":[{"text":"СУПЕР-ЭГО: ","marks":["bold"]},{"text":"По ту сторону есть те, кому ты обязан. Есть те, с кем ты не согласен. Есть и те, кто не согласен с тобой.","marks":["italic"]}],"audioAssetId":null,"voiceId":"super-ego","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"СУПЕР-ЭГО: ","marks":["bold"]},{"text":"Но вы все по-прежнему вместе. Потому что в комнате есть кто-то ","marks":["italic"]},{"text":"третий.","marks":["bold","italic"]}],"audioAssetId":null,"voiceId":"super-ego","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"СУПЕР-ЭГО:","marks":["bold"]},{"text":" ","marks":[]},{"text":"Кто не нравится никому из вас.","marks":["italic"]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-d7bd0ef4-cf81-4a58-a091-766348bfb815","label":"Кто этот третий?","nextNodeId":"node-822d9608-b93e-4750-b08b-fb27e786f265","condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-822d9608-b93e-4750-b08b-fb27e786f265","paragraphs":[{"spans":[{"text":"СУПЕР-ЭГО: ","marks":["bold"]},{"text":"О. Их много.","marks":["italic"]}],"audioAssetId":null,"voiceId":"super-ego","audioLoop":false,"audioVolume":1,"audioStop":false}],"choices":[{"id":"choice-2b89d4ab-73e0-46e6-a633-017aa3a0dbf4","label":"Закончить.","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-b33398af-984c-4a1c-85d0-ab51d3d66831","paragraphs":[{"spans":[{"text":"Это иллюзия. Ты больше никогда не полон сил. Самоубеждение давно перестало работать, и теперь тебе остается лишь отдаться реальности. ","marks":["italic"]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"Познать ее в том самом виде, в котором она всегда прибывала. Без твоего прошлого опыта, который мог искажать твое восприятие. Тебе выпала на редкость уникальная возможность.","marks":["italic"]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"Ты не ","marks":["italic"]},{"text":"определяешь ","marks":["bold","italic"]},{"text":"реальность, но ты ","marks":["italic"]},{"text":"видишь ","marks":["bold","italic"]},{"text":"ее такой, какая она есть. В тебе больше не осталось твоего Я, способного искажать то, каким этот мир является. ","marks":["italic"]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-5bb53701-eb5d-441b-9eee-f42fa5d67f8c","label":"И каким же является этот мир?","nextNodeId":"node-c512770d-7fbf-440c-84ca-9ecff5ff6551","condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-c512770d-7fbf-440c-84ca-9ecff5ff6551","paragraphs":[{"spans":[{"text":"О. Разным. Думаю, ты можешь пока только строить догадки.","marks":["italic"]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-c560a0b0-5c9f-4154-965a-9d41107a3a37","label":"Он удивительно молод и чист. Он непогрешим, изумителен в своей простой красоте.","nextNodeId":"node-8fe466a1-f842-4229-96ab-45405aeaad70","condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[{"type":"changeTrait","kind":"stat","traitId":"stat-8eb3a002-252d-41c3-8b82-7eda776dbbc3","mode":"add","value":1}]},{"id":"choice-0c1e1cdb-e156-4474-b099-e9717ece93e2","label":"Он покрыт плесенью и пылью. Грязный, черный мир, полный разочарований и обид. Отвратительный мир.","nextNodeId":"node-1054d768-d569-4a59-b2cc-2f168e7a95ed","condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[{"type":"changeTrait","kind":"stat","traitId":"stat-8cab4fe6-418f-468a-b4fb-c9e11ed9a2e7","mode":"add","value":1}]},{"id":"choice-a0de0312-b5df-4fbc-97e2-343f88324fd8","label":"Он поразителен в своей неосязаемости. Необъятный, он выглядит как серый туман, в котором ходим мы, светлячки. Каждый видит свой туман, и у каждого он неповторим","nextNodeId":"node-c756510d-3bac-4e50-b837-b803474d92dd","condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[{"type":"changeTrait","kind":"stat","traitId":"stat-0fdce2d6-7757-4491-a081-1ac15c5ee9fc","mode":"add","value":1}]}]},{"id":"node-8fe466a1-f842-4229-96ab-45405aeaad70","paragraphs":[{"spans":[{"text":"ЭГО:","marks":["bold"]},{"text":" Как белый снег, падающий на улицы Инвиды в самый разгар зимы. Этот мир белый, чистый и нетронутый. ","marks":["italic"]}],"audioAssetId":null,"voiceId":"ego","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"ЭГО: ","marks":["bold"]},{"text":"Но кто-то это исправил.","marks":["italic"]}],"audioAssetId":null,"voiceId":"ego","audioLoop":false,"audioVolume":1,"audioStop":false}],"choices":[{"id":"choice-31473a7d-02b9-40a6-b312-3390818788bb","label":"Кто?","nextNodeId":"node-b30d3bcd-d2ca-4476-8d74-9dd04b781231","condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-1054d768-d569-4a59-b2cc-2f168e7a95ed","paragraphs":[{"spans":[{"text":"ЭГО:","marks":["bold"]},{"text":" ","marks":[]},{"text":"Мир абсолютно черный. Сквозь эту темноту не видно ни зги. Словно клубящийся дым из труб Иры, он прорывается в небо, заполоняя собой все вокруг.","marks":["italic"]}],"audioAssetId":null,"voiceId":"ego","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"ЭГО: ","marks":["bold"]},{"text":"Найдется ли тот, кто это исправит?","marks":["italic"]}],"audioAssetId":null,"voiceId":"ego","audioLoop":false,"audioVolume":1,"audioStop":false}],"choices":[{"id":"choice-14404ce2-cd5a-484a-8056-3ed06df04575","label":"Кто?","nextNodeId":"node-b30d3bcd-d2ca-4476-8d74-9dd04b781231","condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-c756510d-3bac-4e50-b837-b803474d92dd","paragraphs":[{"spans":[{"text":"ЭГО: ","marks":["bold"]},{"text":"Мир серый. В оттенках серого мы видим тьму. И мы видим свет. Каждая секунда не похожа на предыдущую. У каждого она своя. ","marks":["italic"]}],"audioAssetId":null,"voiceId":"ego","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"ЭГО: ","marks":["bold"]},{"text":"Мы не можем понять того, что видим сами. И пытаемся понять то, что видят другие. Мы смотрим на один туман. Но узоры его для нас совершенно неповторимы.","marks":["italic"]}],"audioAssetId":null,"voiceId":"ego","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"ЭГО: ","marks":["bold"]},{"text":"И туман этот может быть черным. И может быть белым. ","marks":["italic"]}],"audioAssetId":null,"voiceId":"ego","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"ЭГО: ","marks":["bold"]},{"text":"В мире еще не нашелся тот, кто развеет туман.","marks":["italic"]}],"audioAssetId":null,"voiceId":"ego","audioLoop":false,"audioVolume":1,"audioStop":false}],"choices":[{"id":"choice-360cd2a9-d45a-49e2-8b7e-e0ae9440373d","label":"Кто?","nextNodeId":"node-b30d3bcd-d2ca-4476-8d74-9dd04b781231","condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-b30d3bcd-d2ca-4476-8d74-9dd04b781231","paragraphs":[{"spans":[{"text":"Вы медленно осознаете себя. Сначала кончики пальцев. Запястье. Предплечье. Наконец, плечи. Шею. Затылок. Где-то далеко пульсирует ноющая боль. Давно вами забытая, она спешит напомнить о себе, как только вы открываете глаза...","marks":["italic"]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[]}]},{"id":"script-e337012e-603d-4382-a682-bc09eb7c8334","name":"Кровать","entryNodeId":"node-24da6d30-55d8-4036-97ad-e79e2cc9a377","nodes":[{"id":"node-24da6d30-55d8-4036-97ad-e79e2cc9a377","paragraphs":[{"spans":[{"text":"Вы видите перед собой обычную кровать. По сравнению со всем остальным в квартире, она подозрительно чистая и обычная. Выглядит почти... безопасно.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-02e923e7-88c2-46cc-bbd7-546ec02de975","label":"Лечь спать","nextNodeId":null,"condition":{"type":"compare","source":"time","key":"timeOfDaySeconds","operator":"gt","value":71999},"unavailableReason":"Еще не время спать.","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[{"type":"advanceTime","seconds":32400},{"type":"changeTrait","kind":"stat","traitId":"stat-8eb3a002-252d-41c3-8b82-7eda776dbbc3","mode":"add","value":3}]},{"id":"choice-60ad44b7-91b5-46ee-bb9f-996c42a8da87","label":"Отойти от кровати","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]}]},{"id":"script-319d6558-12d7-4366-b896-eae4529a4bc9","name":"Стул с Рубашкой","entryNodeId":"node-8d945ba3-31f9-4122-b424-a6ff54b3c824","nodes":[{"id":"node-8d945ba3-31f9-4122-b424-a6ff54b3c824","paragraphs":[{"spans":[{"text":"Вы видите перед собой возмутительно неудобный стул. На его спинке неаккуратно развешана белая, помятая рубашка.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-0703fa56-2bb7-435e-8fde-a4d1af4d3753","label":"Никто не будет определять удобство за меня! (Сесть на стул)","nextNodeId":"node-914fe663-a831-46f5-856c-6abdf1a47c70","condition":null,"unavailableReason":"","checkId":"check-5d6954b9-7712-4887-bd81-6028199cebb0","failureNodeId":"node-e1e24527-cc0a-45f3-a4fe-b218d886543c","failureActions":[],"actions":[]},{"id":"choice-a4cd976e-f04b-4f52-a816-8fd86c7dac96","label":"Я доверюсь предчувствию. (Не садиться на стул)","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]},{"id":"choice-4ebef008-e80e-4baa-8269-ade7cd09567c","label":"Забрать рубашку","nextNodeId":"node-ef9d4554-a42e-4243-988c-22ddacc4c240","condition":null,"unavailableReason":"У вас уже есть рубашка.","checkId":null,"usageLimit":{"period":"ever","maxUses":1,"seconds":86400},"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-e1e24527-cc0a-45f3-a4fe-b218d886543c","paragraphs":[{"spans":[{"text":"Вы сели на возмутительно неудобный стул. К сожалению, вы не смогли стерпеть его неудобство. Ваша ","marks":[]},{"text":"МАТЕРИЯ ","marks":["bold"]},{"text":"испытывает ","marks":[]},{"text":"АГОНИЮ","marks":["bold"]},{"text":".","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-d12d5f57-8545-4a78-856f-5cd986b15bcb","label":"Закончить","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[{"type":"changeTrait","kind":"stat","traitId":"stat-0fdce2d6-7757-4491-a081-1ac15c5ee9fc","mode":"add","value":-1}]}]},{"id":"node-914fe663-a831-46f5-856c-6abdf1a47c70","paragraphs":[{"spans":[{"text":"ОНО:","marks":["bold"]},{"text":" Я ","marks":[]},{"text":"устал. Хочу присесть.","marks":["italic"]}],"audioAssetId":null,"voiceId":"ono","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"ЭГО: ","marks":["bold"]},{"text":"К тому же, не такой уж он и неудобный...","marks":["italic"]}],"audioAssetId":null,"voiceId":"ego","audioLoop":false,"audioVolume":1,"audioStop":true}],"choices":[{"id":"choice-937d72ff-9976-4206-9671-075d7b68b687","label":"Продолжить","nextNodeId":"node-c0da84da-f5f8-4efa-b2ab-db573e90815b","condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-c0da84da-f5f8-4efa-b2ab-db573e90815b","paragraphs":[{"spans":[{"text":"Вы сели на возмутительно неудобный стул. Нечто внутри вас подавило жалкие позывы встать с неудобного стула. Ваш ","marks":[]},{"text":"РАЗУМ ","marks":["bold"]},{"text":"торжествует.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-8af22215-c306-42ce-ba1f-f6bd790d38fa","label":"Закончить.","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[{"type":"changeTrait","kind":"stat","traitId":"stat-8cab4fe6-418f-468a-b4fb-c9e11ed9a2e7","mode":"add","value":1}]}]},{"id":"node-ef9d4554-a42e-4243-988c-22ddacc4c240","paragraphs":[{"spans":[{"text":"Вы взяли помятую рубашку в руки. Она выглядит на подозрение ","marks":[]},{"text":"презентабельно","marks":["italic"]},{"text":".","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-83d50727-9fdd-44cf-a04c-17c5ddce85b6","label":"Закончить","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[{"type":"giveItemOnce","itemDefinitionId":"item-915eaca4-c097-4d48-8f0f-00e6afb1ef64","rewardId":"reward-1b66322c-dd2e-4021-bf03-0930e4ef365e"}]}]}]},{"id":"script-0aa65d4b-14c6-42ef-be64-63bfb0bf8ff2","name":"Стол","entryNodeId":"node-8a9f1064-3d50-4731-b55d-815782af5585","nodes":[{"id":"node-8a9f1064-3d50-4731-b55d-815782af5585","paragraphs":[{"spans":[{"text":"Стол вызывает у вас ","marks":[]},{"text":"ужас, ","marks":["italic"]},{"text":"едва вам стоит взглянуть на него. Кипы разбросанных тут и там бумаг кажутся вам отдаленно знакомыми...","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-3855088e-8c71-4a9c-9dc4-cdba24abfe84","label":"Бросить попытки смотреть на стол","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]},{"id":"choice-75afe23e-8365-473a-9574-02edbbccb25e","label":"Попытаться разобрать бумаги","nextNodeId":"node-396bdf5f-bc3b-416b-aa7c-3ecefb5a9d12","condition":{"type":"compare","source":"flag","key":"read","operator":"eq","value":null},"unavailableReason":"","checkId":"check-32501038-472d-406f-bd99-ce8a480d6e3b","failureNodeId":"node-3c5ae134-f19f-4a10-9b84-b15979b6ae6e","failureActions":[],"actions":[]}]},{"id":"node-396bdf5f-bc3b-416b-aa7c-3ecefb5a9d12","paragraphs":[{"spans":[{"text":"СУПЕР-ЭГО:","marks":["bold"]},{"text":" ","marks":[]},{"text":"Нельзя оставлять столько мусора на столе. Ты как ","marks":["italic"]},{"text":"свинья","marks":["bold","italic"]},{"text":".","marks":["italic"]}],"audioAssetId":null,"voiceId":"super-ego","audioLoop":false,"audioVolume":1,"audioStop":true}],"choices":[{"id":"choice-3d87fe99-fb3c-4a26-880e-2df154ee4178","label":"Продолжить","nextNodeId":"node-82b615fa-be00-46db-bcdb-3ae1fb7aedf2","condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[{"type":"advanceTime","seconds":600}]}]},{"id":"node-82b615fa-be00-46db-bcdb-3ae1fb7aedf2","paragraphs":[{"spans":[{"text":"Вы потратили на изучение бумаг около ","marks":[]},{"text":"десяти минут","marks":["bold"]},{"text":". Тут были разные проектные работы, эссе, записки...","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-4b34eaad-16d7-4557-8e25-c90d0e587448","label":"Продолжить","nextNodeId":"node-80e82273-8821-4d67-af2e-7ee5b29f671c","condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-80e82273-8821-4d67-af2e-7ee5b29f671c","paragraphs":[{"spans":[{"text":"Среди них вы нашли и свой читательский билет. Он давал понять, что вы являетесь студентом второго курса местного отделения ","marks":[]},{"text":"Супербианского Университета","marks":["italic"]},{"text":", чтобы это не значило.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-1ddef931-5a9e-4187-a19c-5588a12fb30d","label":"Закончить","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[{"type":"setFlag","key":"read","value":true},{"type":"giveItemOnce","itemDefinitionId":"item-550f8635-7df8-41ee-a45d-0f2c4a29ce3e","rewardId":"reward-9890c6d2-1b7f-41ac-b53b-373ddb8f02b0"}]}]},{"id":"node-3c5ae134-f19f-4a10-9b84-b15979b6ae6e","paragraphs":[{"spans":[{"text":"ОНО: ","marks":["bold"]},{"text":"Зачем нам разбирать эти бумаги? Мне так лень...","marks":["italic"]}],"audioAssetId":null,"voiceId":"ono","audioLoop":false,"audioVolume":0.9,"audioStop":true},{"spans":[{"text":"Потратив некоторое время, вы поняли, что так и не смогли уловить суть написанного. Ваш ","marks":[]},{"text":"РАЗУМ ","marks":["bold"]},{"text":"испытывает вину.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-645f5725-dad5-4a02-a671-9fad82a74b3b","label":"Смириться с поражением","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[{"type":"changeTrait","kind":"stat","traitId":"stat-8cab4fe6-418f-468a-b4fb-c9e11ed9a2e7","mode":"add","value":-1}]}]},{"id":"node-96d6f74a-1d87-4d39-89fd-a55e52b753ee","paragraphs":[{"spans":[{"text":"","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[]}]},{"id":"script-df0a83e3-5186-4f72-8219-4aebe09be01b","name":"Раковина с зеркалом","entryNodeId":"node-0b4fff65-778b-4207-84b7-a90cdb74f710","nodes":[{"id":"node-0b4fff65-778b-4207-84b7-a90cdb74f710","paragraphs":[{"spans":[{"text":"Вы подошли к мутной раковине, обустроенной отдельно от всего остального. Над ним висит странное зеркало.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"ЭГО: ","marks":["bold"]},{"text":"В нем можно увидеть самого себя.","marks":["italic"]}],"audioAssetId":null,"voiceId":"ego","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"Зеркало грязное. Нужно будет постараться, чтобы себя в нем рассмотреть.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-74930513-e811-4322-ba50-4668680b6484","label":"Попытаться разглядеть себя в зеркале","nextNodeId":"node-a52e9b4c-2e0a-4728-96de-c961c5e32631","condition":{"type":"any","conditions":[{"type":"compare","source":"check","key":"check-2fc8197b-406e-4a50-8783-6201980fe1d0","field":"attempts","operator":"lte","value":0}]},"unavailableReason":"Вы уже смотрели на себя в зеркало.","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]},{"id":"choice-d8f64e37-07c9-45f6-976d-151e9a0c27a7","label":"Завершить","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-a52e9b4c-2e0a-4728-96de-c961c5e32631","paragraphs":[{"spans":[{"text":"С большим усилием, вы все же смогли посмотреть на себя. ","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"ЭГО: ","marks":["bold"]},{"text":"Я оказался...","marks":["italic"]}],"audioAssetId":null,"voiceId":"ego","audioLoop":false,"audioVolume":1,"audioStop":false}],"choices":[{"id":"c