Stop":false},{"spans":[{"text":"Вы оказались довольно болезненным юношей. Худое лицо, бледная кожа, и подозрительно короткие клыки.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-b6cf6ae7-719e-432c-8afd-e7cfd523204c","label":"Завершить","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[{"type":"setFlag","key":"bad_looking","value":true}]}]},{"id":"node-265cf325-1663-4dcf-9cfe-d5d9b54f2ab3","paragraphs":[{"spans":[{"text":"ЭГО:","marks":["bold"]},{"text":" ","marks":[]},{"text":"Нужно собрать себя по кусочкам...","marks":["italic"]}],"audioAssetId":null,"voiceId":"ego","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"Да, вы оказались достаточно привлекательной молодой девушкой. При ближайшем рассмотрении оказалось, что у вас довольно коротко спилены два клыка.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-b79c6c02-cafe-4ef5-baf5-fb6964fcaa75","label":"Завершить","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[{"type":"setFlag","key":"good_looking","value":true}]}]},{"id":"node-90dd1604-2141-4b48-9883-8e0bb922cf5d","paragraphs":[{"spans":[{"text":"ЭГО:","marks":["bold"]},{"text":" ","marks":[]},{"text":"Слишком многое оказалось забыто...","marks":["italic"]}],"audioAssetId":null,"voiceId":"ego","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"Вы оказались довольно болезненной девушкой. Худое лицо, бледная кожа, и подозрительно короткие клыки.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-7f41b1f3-6eb4-40f9-a9f6-56f376c9b255","label":"Завершить.","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[{"type":"setFlag","key":"bad_looking","value":true}]}]}]},{"id":"script-1a8588bf-2ca2-4e6f-8da2-a8873e24058f","name":"Туалет","entryNodeId":"node-516b0ce5-4b3c-4e9c-b0f5-13708129e865","nodes":[{"id":"node-516b0ce5-4b3c-4e9c-b0f5-13708129e865","paragraphs":[{"spans":[{"text":"Обычный унитаз. Если не обращать внимание на то, сколько лет он здесь служит.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"ОНО: ","marks":["bold"]},{"text":"Нужда зовет.","marks":["italic"]}],"audioAssetId":null,"voiceId":"ono","audioLoop":false,"audioVolume":1,"audioStop":false}],"choices":[{"id":"choice-3116fb99-b065-42d5-91ec-50f6ce008aaf","label":"Справить нужду.","nextNodeId":"node-528d6360-364b-4953-bd06-be2136a90dcc","condition":{"type":"compare","source":"flag","key":"pp","operator":"eq","value":true},"unavailableReason":"Вы уже справили нужду.","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[{"type":"setFlag","key":"pp","value":false}]},{"id":"choice-75d91c2c-ee8b-4647-a4f0-8e36b08f08c1","label":"Отойти.","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-528d6360-364b-4953-bd06-be2136a90dcc","paragraphs":[{"spans":[{"text":"Вы решили справить нужду. Приятное облегчение объяло ваше тело.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"Однако, уже покончив с этим делом, вы обнаружили среди ржавчины странный кусок блеска, который вовсе не был похож на человеческие экскременты. ","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-a838c9df-ef93-4a56-9a2b-93bb27130a04","label":"Достать предмет","nextNodeId":"node-8ea57b35-330b-47ab-8eca-509d243ca297","condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[{"type":"giveItemOnce","itemDefinitionId":"item-5c5675cf-67aa-48dc-9faa-b91c1256a7b2","rewardId":"reward-51f03ade-81c0-40bc-851b-034eaf0a5551"}]},{"id":"choice-742d7d0e-d07b-4f1f-9cf0-f1c6a837c3b0","label":"Да ни за что!","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-8ea57b35-330b-47ab-8eca-509d243ca297","paragraphs":[{"spans":[{"text":"Вы достали блестящий предмет. Бакелитовая поверхность его, матовая и блестящая, была покрыта приятным белым цветом. Неаккуратным ручным подчерком было написано, что это - визитка.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-124d6fb3-d3cf-4a40-8b5a-d834264ecc0a","label":"Чья это визитка?","nextNodeId":"node-9e94eff3-e2da-4a46-94dc-3db1e36db2f8","condition":{"type":"any","conditions":[{"type":"compare","source":"status","key":"status-dd5589a2-139f-43b1-8e2e-634dfb01edd2","operator":"eq","value":true}]},"unavailableReason":"Вы не познали эту часть себя.","checkId":"check-a343dc31-dc96-4932-8c97-b276201321c0","failureNodeId":"node-e12b77a2-bd9f-40e3-a4a5-5ad93265ed9c","failureActions":[],"actions":[]},{"id":"choice-fc9e5db8-4e7f-42a1-be9f-886e019db95a","label":"Чья это визитка?","nextNodeId":"node-4486c2ad-31c2-4855-8244-145cabb2e2a0","condition":{"type":"compare","source":"status","key":"status-e8b2a38e-a7fb-4442-b1ad-7dac4214938b","operator":"eq","value":true},"unavailableReason":"Вы не познали эту часть себя.","checkId":"check-a343dc31-dc96-4932-8c97-b276201321c0","failureNodeId":"node-992a5ad1-ff15-41a0-8cfa-4aac861d5535","failureActions":[],"actions":[]},{"id":"choice-20b786c2-7092-4481-9112-16df186b7e93","label":"Положить визитку в карман.","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-9e94eff3-e2da-4a46-94dc-3db1e36db2f8","paragraphs":[{"spans":[{"text":"ЭГО: ","marks":["bold"]},{"text":"Почерк... Фотография... Мы где-то уже все это видели. Худые скулы. Бледная кожа. Черные, пепельные волосы.","marks":["italic"]}],"audioAssetId":null,"voiceId":"ego","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"Вы узнаете на этой визитке ","marks":[]},{"text":"себя. ","marks":["bold"]},{"text":"Принадлежит она скромному аптекарю с инициалами А.М.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-f28ed542-a711-4a1a-a18f-f8e24a66166f","label":"Завершить","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-e12b77a2-bd9f-40e3-a4a5-5ad93265ed9c","paragraphs":[{"spans":[{"text":"ЭГО: ","marks":["bold"]},{"text":"Закарючки выглядят незнакомыми... чужеродными.","marks":["italic"]}],"audioAssetId":null,"voiceId":"ego","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"Вам не удалось установить, кому принадлежит эта визитка. Вы поняли только, что ее владелец - аптекарь. На обороте заботливо обозначен адрес.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-1a81ee40-6abe-40fa-be61-6d8cda58905d","label":"Завершить.","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-4486c2ad-31c2-4855-8244-145cabb2e2a0","paragraphs":[{"spans":[{"text":"ЭГО:","marks":["bold"]},{"text":" ","marks":[]},{"text":"Почерк... Фотография... Мы где-то уже все это видели. Худые скулы. Бледная кожа. Черные, пепельные волосы.","marks":["italic"]}],"audioAssetId":null,"voiceId":"ego","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"Вы узнаете на этой визитке себя. Принадлежит она скромной аптекарше с инициалами А.М.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-35cc90c5-5280-4aea-838a-82b2a2a211b7","label":"Завершить","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-992a5ad1-ff15-41a0-8cfa-4aac861d5535","paragraphs":[{"spans":[{"text":"ЭГО:","marks":["bold"]},{"text":" ","marks":[]},{"text":"Закарючки выглядят незнакомыми... чужеродными.","marks":["italic"]}],"audioAssetId":null,"voiceId":"ego","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"Вам не удалось установить, кому принадлежит эта визитка. Вы поняли только, что ее владелец - аптекарь. На обороте заботливо обозначен адрес.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-13223277-ffc4-4786-95f1-cdb40ddb2abb","label":"Завершить","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]}]},{"id":"script-c1860230-11e9-44fb-9ffa-991f19ac3a65","name":"Ванна.","entryNodeId":"node-ce68fa30-bbe1-441d-969e-503edf34abbe","nodes":[{"id":"node-ce68fa30-bbe1-441d-969e-503edf34abbe","paragraphs":[{"spans":[{"text":"Перед тобой ванная. Она странным образом изогнута по бокам, подобая пасти неизвестного зверя.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-9121679c-ea68-4bd4-849b-f00cd4e0b285","label":"Заглянуть в ванну","nextNodeId":"node-dfb44f4d-c7f5-4779-9b05-a0183e1d94f0","condition":null,"unavailableReason":"","checkId":null,"usageLimit":{"period":"ever","maxUses":1,"seconds":86400},"failureNodeId":null,"failureActions":[],"actions":[]},{"id":"choice-f75a9bc9-548c-47d1-b1fb-73d0aae7b836","label":"Попытаться набрать ванну","nextNodeId":"node-55bdcda2-b30b-4f91-9d0b-cb9b89a28c12","condition":null,"unavailableReason":"","checkId":null,"usageLimit":{"period":"day","maxUses":1,"seconds":86400},"failureNodeId":null,"failureActions":[],"actions":[]},{"id":"choice-5e1a717e-a5d2-42b9-831a-ea781b650977","label":"Завершить","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-dfb44f4d-c7f5-4779-9b05-a0183e1d94f0","paragraphs":[{"spans":[{"text":"Вы заглянули в пустующую, ржавую пасть чугунного монстра.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"Внутри вы увидели одинокую баночку, неизвестного вам происхождения.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-36957627-7914-48c9-958f-b575eebbceb2","label":"Потянуться за баночкой","nextNodeId":"node-100751a6-2882-4d45-a19c-fcb5c708b900","condition":null,"unavailableReason":"","checkId":null,"usageLimit":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-55bdcda2-b30b-4f91-9d0b-cb9b89a28c12","paragraphs":[{"spans":[{"text":"Ванная наполнилась водой ржавого цвета примерно наполовину. Вода была едва теплой, но все равно лучше, чем холод во всей остальной квартире.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-2994c112-3d90-42d9-9404-9afd1860a598","label":"Принять ванну","nextNodeId":"node-4f6f8670-68ab-4830-82c2-b8f4306f0be1","condition":null,"unavailableReason":"","checkId":null,"usageLimit":{"period":"day","maxUses":1,"seconds":86400},"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-100751a6-2882-4d45-a19c-fcb5c708b900","paragraphs":[{"spans":[{"text":"Открыв баночку, подозрительно напоминающую аптечную, вы обнаружили, что это действительно препарат, который называется «Параколум». К сожалению свойства его вы узнать не смогли.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-4041824a-5d01-44c5-86ec-f432ed0feab1","label":"Забрать банку","nextNodeId":"node-88bc1a9c-55dd-4734-9991-b57d9b2a96bc","condition":null,"unavailableReason":"","checkId":"check-b1885d38-2c00-4efb-afe3-e9110349b698","failureNodeId":null,"failureActions":[{"type":"giveItemOnce","itemDefinitionId":"item-8c5b2546-3951-433a-98dc-bb894b813916","rewardId":"reward-f40183be-22c6-4298-bfac-5ddbe6f8f02d"}],"actions":[{"type":"giveItemOnce","itemDefinitionId":"item-8c5b2546-3951-433a-98dc-bb894b813916","rewardId":"reward-5665c61d-e27e-4beb-bd83-a3fd236b2ef0"}]},{"id":"choice-23296467-b05c-48e7-a92c-1ffbaa1ccc13","label":"Оставить банку в покое","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-88bc1a9c-55dd-4734-9991-b57d9b2a96bc","paragraphs":[{"spans":[{"text":"ЭГО: ","marks":["bold"]},{"text":"Параколум...","marks":["italic"]}],"audioAssetId":null,"voiceId":"ego","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"ОНО: ","marks":["bold"]},{"text":"Звучит мягко. И тепло. Он утолял твою боль прежде. Теперь ты спасешь его от одиночества.","marks":["italic"]}],"audioAssetId":null,"voiceId":"ono","audioLoop":false,"audioVolume":1,"audioStop":false}],"choices":[{"id":"choice-291f7ee2-a80a-4d4a-80bb-a94c5db990b4","label":"Заврешить","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-4f6f8670-68ab-4830-82c2-b8f4306f0be1","paragraphs":[{"spans":[{"text":"Теплая вода обволакивает ваше тело. Вы медленно погружаетесь в легкую степень расслабления, когда понимаете, что вода уже остыла. Ваша ","marks":[]},{"text":"МАТЕРИЯ","marks":["bold"]},{"text":" удовлетворена.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-45568876-8d37-4e71-bf8c-a8c24fa7d782","label":"Завершить","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[{"type":"changeTrait","kind":"stat","traitId":"stat-0fdce2d6-7757-4491-a081-1ac15c5ee9fc","mode":"add","value":1}]}]}]},{"id":"script-022a1341-a8d5-47e2-be3a-c4ef5d7b8398","name":"Икона","entryNodeId":"node-cadd4cec-c664-442e-a0f4-12f382f0e414","nodes":[{"id":"node-cadd4cec-c664-442e-a0f4-12f382f0e414","paragraphs":[{"spans":[{"text":"Икона с изображением некоего святого. Почему-то расположена на полу.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"ЭГО: ","marks":["bold"]},{"text":"Он выглядит... опечаленным.","marks":["italic"]}],"audioAssetId":null,"voiceId":"ego","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"СУПЕР-ЭГО: ","marks":["bold"]},{"text":"Нельзя позволить иконе оставаться на полу. Это ","marks":["italic"]},{"text":"богохульство.","marks":["bold","italic"]}],"audioAssetId":null,"voiceId":"super-ego","audioLoop":false,"audioVolume":1,"audioStop":false}],"choices":[{"id":"choice-3400ef77-77d3-494b-9f41-84c62847bff2","label":"Повесить святого обратно.","nextNodeId":"node-14e84868-75ef-4111-a84e-dcefddd4d18d","condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[{"type":"setFlag","key":"up_icon","value":true}]},{"id":"choice-e1531017-8140-4b91-a884-3af8e1b45de4","label":"Оставить святого в одиночестве.","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]},{"id":"choice-8ea7cf8d-554b-434b-8404-5eb2ed656f30","label":"Выкинуть икону.","nextNodeId":"node-ab8a7ee6-92a1-45fa-8288-93cab503f1f9","condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[{"type":"setFlag","key":"gone_icon","value":true}]}]},{"id":"node-14e84868-75ef-4111-a84e-dcefddd4d18d","paragraphs":[{"spans":[{"text":"Вы бережно подняли икону и повесили ее обратно на угловое крепление. Святой здесь выглядит чуть лучше.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-60c509b5-4a92-4e8b-b6c1-8eef528ebfc0","label":"Закончить","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-ab8a7ee6-92a1-45fa-8288-93cab503f1f9","paragraphs":[{"spans":[{"text":"Вы избавились от иконы, укрывшись от взгляда святого. ","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"СУПЕР-ЭГО: ","marks":["bold"]},{"text":"Но надолго ли?","marks":["italic"]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-799e8b4c-29f9-4b8f-8869-fc12dab4a5b4","label":"Закончить","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]}]},{"id":"script-def5a56a-e9fb-450f-8c9e-805234a69c98","name":"Картина","entryNodeId":"node-dc676d53-6b42-4f4c-9402-9c3e2cdd2b1c","nodes":[{"id":"node-dc676d53-6b42-4f4c-9402-9c3e2cdd2b1c","paragraphs":[{"spans":[{"text":"Перед вами картина. Она странным образом отличается своим богатством от остальной квартиры.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"На ней изображен благородный дворянин, напоказ демонстрирующий свои клыки и надменный взгляд.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"Кажется, он смотрит вам прямо в душу. И недоволен тем, что видит.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"СУПЕР-ЭГО: ","marks":["bold"]},{"text":"Он недоволен нашим моральным разложением.","marks":["italic"]}],"audioAssetId":null,"voiceId":"ego","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"ОНО: ","marks":["bold"]},{"text":"Нашей слабостью.","marks":["italic"]}],"audioAssetId":null,"voiceId":"ono","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"ЭГО: ","marks":["bold"]},{"text":"Он хотел видеть кого-то другого.","marks":["italic"]}],"audioAssetId":null,"voiceId":"ego","audioLoop":false,"audioVolume":1,"audioStop":false}],"choices":[{"id":"choice-df8e2d8a-019f-4a4b-a65b-641870611d6b","label":"Протереть картину","nextNodeId":"node-2aea72e6-ac2c-41eb-a37e-b92a15d807bd","condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]},{"id":"choice-864f4fe4-f291-4be2-a028-6fe0e3d4dd14","label":"Оставить портрет в покое.","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-2aea72e6-ac2c-41eb-a37e-b92a15d807bd","paragraphs":[{"spans":[{"text":"Ваша ладонь почти сразу покрылась устойчивым слоем пыли. К портрету давно не прикасались. Работа же была выполнена на редкость качественно: краска нигде не испортилась и не выцвела.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-59e6adae-3c97-437b-bd96-7849967b3351","label":"Попробовать понять, кто это.","nextNodeId":"node-088852ae-c4cf-48c3-b94a-64f99851b2d8","condition":null,"unavailableReason":"","checkId":"check-ec5fdf4e-e2d6-4e29-b3fb-52738b6124ff","failureNodeId":"node-5ce355b3-a312-494c-aebe-09cf243c1adc","failureActions":[],"actions":[]},{"id":"choice-fbeb304f-cdb1-49be-a2fb-e2d2c4c4cd2f","label":"Закончить с картиной.","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-088852ae-c4cf-48c3-b94a-64f99851b2d8","paragraphs":[{"spans":[{"text":"ЭГО: ","marks":["bold"]},{"text":"Мы знаем, кто это.","marks":["italic"]}],"audioAssetId":null,"voiceId":"ego","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"ЭГО: ","marks":["bold"]},{"text":"Наш дед по линии матери. Морис Мортариум. В свое время он построил успешную военную службу. Погиб, как водится, где-то в окопе.","marks":["italic"]}],"audioAssetId":null,"voiceId":"ego","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"ОНО:","marks":["bold"]},{"text":" ","marks":["bold","italic"]},{"text":"Он выглядит сильным.","marks":["italic"]}],"audioAssetId":null,"voiceId":"ono","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"СУПЕР-ЭГО:","marks":["bold"]},{"text":" ","marks":[]},{"text":"И он таким был.","marks":["italic"]}],"audioAssetId":null,"voiceId":"super-ego","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"ЭГО:","marks":["bold"]},{"text":" ","marks":[]},{"text":"А мы?..","marks":["italic"]}],"audioAssetId":null,"voiceId":"ego","audioLoop":false,"audioVolume":1,"audioStop":false}],"choices":[{"id":"choice-8bab9277-592f-4b64-b0a2-5b07a37d5d83","label":"Завершить","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-5ce355b3-a312-494c-aebe-09cf243c1adc","paragraphs":[{"spans":[{"text":"Вы поняли, что не можете понять, кто это. Но угадать причину его недовольства было несложно.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"СУПЕР-ЭГО:","marks":["bold"]},{"text":" ","marks":[]},{"text":"За его спиной простирается мир. Прекрасный, романтический образ прошлого. Он же смотрит на нас. Своих потомков из будущего, для нас - настоящего.","marks":["italic"]}],"audioAssetId":null,"voiceId":"super-ego","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"СУПЕР-ЭГО: ","marks":["bold"]},{"text":"И ему не нравится то, что он видит.","marks":["italic"]}],"audioAssetId":null,"voiceId":"super-ego","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"ОНО: ","marks":["bold"]},{"text":"На его фоне наши клыки ощущаются слишком короткими и тупыми. ","marks":["italic"]}],"audioAssetId":null,"voiceId":"ono","audioLoop":false,"audioVolume":1,"audioStop":false}],"choices":[{"id":"choice-5c16d542-dc2a-46f9-85cd-8c0b32425271","label":"Завершить.","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]}]},{"id":"script-04af5917-9059-448c-a67e-826292953764","name":"Раковина","entryNodeId":"node-80b4ab33-d14b-453a-89ae-e46690547be9","nodes":[{"id":"node-80b4ab33-d14b-453a-89ae-e46690547be9","paragraphs":[{"spans":[{"text":"Ржавая раковина. С виду кажется довольно бездонной.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"Где-то в глубине трубы виднеется отблеск металла.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-149648e6-91ee-49c8-95ce-8ee48f33bc32","label":"Потянуться внутрь.","nextNodeId":"node-12b0744d-61d4-4560-b851-a204b41b1940","condition":{"type":"compare","source":"inventory","key":"item-6f5a3fe6-4a08-4eaa-8c78-1dbc3a345b69","operator":"lte","value":0},"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]},{"id":"choice-4cb0494e-87ac-4759-9f60-3681fb5fa0dd","label":"Завершить.","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-12b0744d-61d4-4560-b851-a204b41b1940","paragraphs":[{"spans":[{"text":"Вы сунули в раковину руку по локоть.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"С большим трудом вы достали... Ключ. Обычный старый ключ, который выглядит довольно острым.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-e55a7777-1f89-46be-ad2d-792fef6b9db4","label":"Завершить","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[{"type":"giveItemOnce","itemDefinitionId":"item-6f5a3fe6-4a08-4eaa-8c78-1dbc3a345b69","rewardId":"reward-72223b72-aa59-400f-befb-835ea8f7480d"}]}]}]},{"id":"script-7456dae5-91ba-43af-8b10-0711613b9b29","name":"Шкафчик","entryNodeId":"node-46a3c346-be72-43a6-bf4f-cab1bb957633","nodes":[{"id":"node-46a3c346-be72-43a6-bf4f-cab1bb957633","paragraphs":[{"spans":[{"text":"Шкафчик под действием влаги странно разбух, он кажется совершенно не подходящим для хранения вещей.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"Тем не менее внутри вы обнаружили какие то бумаги и карманные часы.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-185b6b99-7d91-49fb-89e9-b96357aba04b","label":"Забрать часы.","nextNodeId":"node-46a3c346-be72-43a6-bf4f-cab1bb957633","condition":{"type":"compare","source":"inventory","key":"item-40c7857d-575a-445d-9bc0-23e6a8cd8807","operator":"lte","value":0},"unavailableReason":"","checkId":null,"usageLimit":{"period":"ever","maxUses":1,"seconds":86400},"failureNodeId":null,"failureActions":[],"actions":[{"type":"giveItemOnce","itemDefinitionId":"item-40c7857d-575a-445d-9bc0-23e6a8cd8807","rewardId":"reward-aad72f70-3662-4bc7-aba0-3a6b8293c771"}]},{"id":"choice-43983ec7-52c7-45f5-bd61-cbc41f536195","label":"Попытаться разобрать бумаги","nextNodeId":"node-124608ed-9ba1-413b-83ef-27bb989d0497","condition":null,"unavailableReason":"","checkId":"check-239783ca-d3cd-4702-8347-e024f88a5c5f","usageLimit":null,"failureNodeId":"node-58f603b8-85d3-4dc2-a607-66dcceee8b38","failureActions":[],"actions":[]},{"id":"choice-bf1537d6-8031-4958-8ea5-6e1eb123c6ed","label":"Завершить.","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-124608ed-9ba1-413b-83ef-27bb989d0497","paragraphs":[{"spans":[{"text":"СУПЕР-ЭГО: ","marks":["bold"]},{"text":"Сосредоточься.","marks":["italic"]}],"audioAssetId":null,"voiceId":"super-ego","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"СУПЕР-ЭГО: ","marks":["bold"]},{"text":"История болезни, некоего А.М. Он пережил операцию по спиливанию зубов.","marks":["italic"]}],"audioAssetId":null,"voiceId":"super-ego","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"СУПЕР-ЭГО:","marks":["bold"]},{"text":" Все бумаги - история болезни.","marks":["italic"]}],"audioAssetId":null,"voiceId":"super-ego","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"ЭГО: ","marks":["bold"]},{"text":"Это... наше?","marks":["italic"]}],"audioAssetId":null,"voiceId":"ego","audioLoop":false,"audioVolume":1,"audioStop":false}],"choices":[{"id":"choice-5a0e9a1d-87aa-4c77-ba8c-ba12c0db2946","label":"Завершить","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-58f603b8-85d3-4dc2-a607-66dcceee8b38","paragraphs":[{"spans":[{"text":"Бумаги приведены в абсолютный беспорядок. Вам удалось выяснить лишь, что это - история болезни.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-d16d7a62-531f-47e7-9b50-f6de43923982","label":"Завершить","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]}]},{"id":"script-ed7c979b-3718-40ae-9973-f0bf988f3e85","name":"Окно","entryNodeId":"node-c4480835-593a-4882-83c5-85997804fd94","nodes":[{"id":"node-c4480835-593a-4882-83c5-85997804fd94","paragraphs":[{"spans":[{"text":"Вы выглядываете в окно как раз в момент, когда над вашей квартирой проносится монорельс.","marks":[]}],"audioAssetId":"22386129-1cb0-411e-b4ab-f679832beadc","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"Железный монстр несется вперед, пока за ним тянется черный след из клубов дыма. ","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"Кошка, мирно спавшая на рельсах, спрыгнула вниз. Приземлилась в мусорный бак у какого-то заведения.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"Бак перевернулся. Разгневанный хозяин заведения, коренастый старичок, тщетно пытался преследовать виновницу.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-6a779507-e432-4810-aedd-e9037615d214","label":"Присмотреться к зданиям","nextNodeId":"node-ebb09617-5a9a-4b31-80ca-6ff30bfc8780","condition":null,"unavailableReason":"","checkId":"check-799a9944-b943-4153-90fa-061f6eb582e4","usageLimit":{"period":"ever","maxUses":1,"seconds":86400},"failureNodeId":"node-d34de10f-b633-4d3d-9cda-fc6077e9940f","failureActions":[],"actions":[]},{"id":"choice-012c0ef6-cb19-4852-a6fa-0bcf7264bc5a","label":"Закончить","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-ebb09617-5a9a-4b31-80ca-6ff30bfc8780","paragraphs":[{"spans":[{"text":"Вы внимательнее взглянули наружу. Здания кажутся вам отдаленно знакомыми.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"СУПЕР-ЭГО:","marks":["bold"]},{"text":" ","marks":[]},{"text":"Конечно, они нам знакомы. Мы не можем не знать этого, как один из жителей этого города.","marks":["italic"]}],"audioAssetId":null,"voiceId":"super-ego","audioLoop":false,"audioVolume":1,"audioStop":false},{"spans":[{"text":"По центру расположена военная академия. Монументальное здание, ныне доживающее свои последние дни в мире пост-беллум.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"Левее - собор имени святого Паисия. ","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"Правее - мертвые районы. Безмолвные трубы уже не кашляют черными клубами дыма.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"СУПЕР-ЭГО:","marks":["bold"]},{"text":" ","marks":[]},{"text":"Весь город ","marks":["italic"]},{"text":"молчит","marks":["bold","italic"]},{"text":".","marks":["italic"]}],"audioAssetId":null,"voiceId":"super-ego","audioLoop":false,"audioVolume":1,"audioStop":false}],"choices":[{"id":"choice-81ce2f83-bf29-4804-8994-30a14e726ab1","label":"Закончить.","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-d34de10f-b633-4d3d-9cda-fc6077e9940f","paragraphs":[{"spans":[{"text":"Здания выглядят странно.","marks":["italic"]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"Узкие, высокие, нависающие и тянущиеся друг к другу. Узкие улочки образуют тонкие коридоры, зачастую перекрытые полотнами ткани, прежде защищавшие жителей от жары.","marks":["italic"]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"Но сейчас трубы промышленных гигантов молчат. Огни монументальных зданий не горят. Колокола собора больше не звенят.","marks":["italic"]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"ОНО: ","marks":["bold"]},{"text":"Город ","marks":["italic"]},{"text":"умер.","marks":["bold","italic"]}],"audioAssetId":null,"voiceId":"ono","audioLoop":false,"audioVolume":1,"audioStop":false}],"choices":[{"id":"choice-ea6e55b4-5b11-4a41-9f7e-710e6c081b46","label":"Закончить","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]}]},{"id":"script-6460a394-fdad-4ac5-95d8-7ed23aa19bab","name":"Окно2","entryNodeId":"node-0d658c58-e634-4a7c-ac5e-2a8ded5309e9","nodes":[{"id":"node-0d658c58-e634-4a7c-ac5e-2a8ded5309e9","paragraphs":[{"spans":[{"text":"Дневной город гудел своим многообразием. Под окнами, мимо постоянно проносилась всевозможная техника. Вы подметили пару двухколесных экземпляров, несколько трехколесных и квартет четырехколесных.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"В здании напротив не горел свет. Оно молчало, а сквозь тоненькие занавески просматривался чужой быт. Но сейчас в нем не было его жителей. В этот час оно уже пустовало.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"Стекло постоянно задевали ветви голого дерева, отстукивая странную, хаотичную мелодию.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1},{"spans":[{"text":"Внизу за остатки хлебных крошек активно сражались вороны.","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-82b7a827-b757-45fc-ba71-87840341d885","label":"Осмотреть цветок, стоящий на подоконнике.","nextNodeId":"node-aa31284f-2741-4820-a766-c997aee56c8c","condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]},{"id":"choice-4c52d900-96a3-4553-b8de-61e12fa1e284","label":"Закончить.","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-aa31284f-2741-4820-a766-c997aee56c8c","paragraphs":[{"spans":[{"text":"На подоконнике расположен горшок, в котором посажен неизвестное растение. ","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-902029d2-c6fe-459c-92cf-ef893689687f","label":"Осмотреть растение.","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]}]}],"rules":[{"id":"rule-a1b30c04-3f5d-4491-ac13-690073249037","name":"Мусор в мусоропровод","trigger":"useItem","targetObjectId":"object-2f38a0ef-77bd-49f5-bec8-01be0f56ce64","checkId":null,"itemDefinitionId":null,"itemTag":"мусор","priority":0,"condition":{"type":"literal","value":true},"unavailableReason":"Это не мусор.","actions":[{"type":"consumeUsedItem"}],"once":false},{"id":"rule-554f81ee-61f8-4d1e-bde2-873e14fe34b3","name":"Новая реакция","trigger":"interact","targetObjectId":null,"checkId":null,"itemDefinitionId":null,"itemTag":null,"priority":0,"condition":null,"unavailableReason":"","actions":[],"once":false}],"checks":[{"id":"check-5d6954b9-7712-4887-bd81-6028199cebb0","name":"Стул","skillId":"skill-bfb72caf-6fe4-4457-a5b8-03b594a7b1af","statId":null,"difficulty":10,"repeatable":true,"retryWhen":{"type":"compare","source":"skill","key":"skill-bfb72caf-6fe4-4457-a5b8-03b594a7b1af","operator":"gt","value":7},"retryReason":"Вам не хватает ХРАРОСТИ чтобы попробовать снова.","maxAttempts":2},{"id":"check-32501038-472d-406f-bd99-ce8a480d6e3b","name":"Стол_бумага","skillId":"skill-d8d