3fd1b62d-bb9e-4354-ad86-f3b87ceacd3a","showsTime":false,"equipmentSlot":null,"capacityBonus":0,"modifiers":{}},{"id":"item-af8ec41a-39d8-4d28-891f-f5bd9e2b5607","name":"Мятая Бумага","description":"Комок мятой бумаги. Когда-то была использована и выброшена.","tags":["мусор"],"imageAssetId":"cad3fa92-59ce-45ae-967e-4e2517d3c7b9","showsTime":false,"equipmentSlot":null,"capacityBonus":0,"modifiers":{}},{"id":"item-17194795-3c51-414d-ad11-ae462cf49414","name":"Пустая Бутылка","description":"Пустая бутылка. На этикетке написано «Caleste»","tags":["мусор"],"imageAssetId":"77125a25-b788-4adf-90a7-cea5d4b9257c","showsTime":false,"equipmentSlot":null,"capacityBonus":0,"modifiers":{}},{"id":"item-550f8635-7df8-41ee-a45d-0f2c4a29ce3e","name":"Читательский билет","description":"Небольшая книжечка в тонкой кожаной обертке, которая указывает на то, что вы являетесь студентом Супербианского Университета. Она позволяет свободно брать книги из местной библиотеки.","tags":[],"imageAssetId":"6e18cee8-ed64-4efa-bc49-50cfbd041729","showsTime":false,"equipmentSlot":null,"capacityBonus":0,"modifiers":{}},{"id":"item-6f5a3fe6-4a08-4eaa-8c78-1dbc3a345b69","name":"Ключ","description":"Домашний ключ. По всей видимости, от вашей квартиры. Зубцы кажутся такими острыми, будто они готовы откусить от вас кусок.","tags":[],"imageAssetId":"3adafbdb-6aab-413c-a831-8fdf70e6716c","showsTime":false,"equipmentSlot":null,"capacityBonus":0,"modifiers":{}},{"id":"item-40c7857d-575a-445d-9bc0-23e6a8cd8807","name":"Карманные часы","description":"Странные карманные часы. Холодная, тяжелая латунь упрямо тянет вашу ладонь вниз. Кажется, от этой тяжести само время течет по другому...","tags":[],"imageAssetId":"94f69584-7ba0-4496-b564-d218a5a16377","showsTime":true,"equipmentSlot":null,"capacityBonus":0,"modifiers":{}},{"id":"item-c6574c1b-92b2-4efe-86f8-99c70f73a04a","name":"Портфель","description":"","tags":[],"imageAssetId":null,"showsTime":false,"equipmentSlot":"accessory","capacityBonus":3,"modifiers":{"skill-d8d2f316-1478-4bf7-aba1-6b1dce769113":1}},{"id":"item-5c5675cf-67aa-48dc-9faa-b91c1256a7b2","name":"Визитка","description":"Визитка некоего аптекаря, который разместил свой бизнес на проспекте святого Паисия, дом 13. Также указан номер телеграфа по адресу Гарро-Вия, дом 26.","tags":[],"imageAssetId":"4e104fad-8f47-4cec-8ff8-af0762cc552c","showsTime":false,"equipmentSlot":null,"capacityBonus":0,"modifiers":{}},{"id":"item-8c5b2546-3951-433a-98dc-bb894b813916","name":"Баночка «Параколума»","description":"Небольшая медицинская баночка, с таблетками параколума внутри. Параколум - опиоидный препарат обезболивающего действия.","tags":[],"imageAssetId":"e36b1e79-48eb-4167-9289-e8e44b662da5","showsTime":false,"equipmentSlot":null,"capacityBonus":0,"modifiers":{}},{"id":"item-3416acf1-e873-4b72-8bc5-fb0e023e408a","name":"Брюки","description":"Довольно широкие брюки. В них достаточно просторно, чтобы пронести две бутылки вина.","tags":[],"imageAssetId":"489d2698-980a-4167-9725-2a893ea00fcd","showsTime":false,"equipmentSlot":"legs","capacityBonus":1,"modifiers":{}},{"id":"item-502588f0-d866-4f80-a255-26c627390e71","name":"Туфли","description":"Обычные удобные туфли. Защитят ваши стопы от асфальта.","tags":[],"imageAssetId":"d212d6be-aebb-44d6-8d2b-ad4bc8c52f37","showsTime":false,"equipmentSlot":"feet","capacityBonus":0,"modifiers":{}},{"id":"item-1f75c10a-d40d-4b65-9d95-52c615cc3551","name":"Мука","description":"Небольшой мешочек муки.","tags":["ингридиент"],"imageAssetId":null,"showsTime":false,"equipmentSlot":null,"capacityBonus":0,"modifiers":{}},{"id":"item-0c04e031-50bb-4b97-80fd-576e54c07791","name":"Вода","description":"Небольшой бурдюк с водой.","tags":["ингридиент"],"imageAssetId":null,"showsTime":false,"equipmentSlot":null,"capacityBonus":0,"modifiers":{}},{"id":"item-73da8a53-1e15-4330-9afb-0b02ad62787b","name":"Хлеб","description":"Кусочек хлеба","tags":[],"imageAssetId":null,"showsTime":false,"equipmentSlot":null,"capacityBonus":0,"modifiers":{}}],"character":{"name":"...","stats":[{"id":"stat-8cab4fe6-418f-468a-b4fb-c9e11ed9a2e7","name":"РАЗУМ","initial":1,"min":0,"max":10,"description":"Ваш РАЗУМ. Нематериальное, эмпирическое, эмоциональное. Стремится к знаниям, самосовершенствованию, познанию мира.","barAssets":{"frameAssetId":null,"fillAssetId":null}},{"id":"stat-0fdce2d6-7757-4491-a081-1ac15c5ee9fc","name":"МАТЕРИЯ","initial":5,"min":0,"max":10,"description":"Ваша МАТЕРИЯ. Она физическая, механистическая, осознает мир через материальные органы чувств."},{"id":"stat-8eb3a002-252d-41c3-8b82-7eda776dbbc3","name":"ПОТЕНЦИЯ","initial":1,"min":0,"max":10,"description":"Ваша ПОТЕНЦИЯ. Ваша способность к осуществлению замыслов. Материальная и мыслительная готовность к реализации действий."}],"skills":[{"id":"skill-bfb72caf-6fe4-4457-a5b8-03b594a7b1af","name":"«Оно»","initial":1,"min":0,"max":10,"description":"Нечто глубинное, не поддающееся объяснению, заложенное в самой варварской глубине человеческого самосознания. Подчиняется только законам природы, потакая инстинктам.","imageAssetId":"5c06595a-f745-4d2b-9ec0-ceeff2d007e5","imageVariants":[]},{"id":"skill-3bb54cd9-0db5-4243-871d-37b504d7523b","name":"«Эго»","initial":1,"min":0,"max":10,"description":"Это Вы. То, как вы понимаете собственное Я. Оно получает информацию, воспринимает мир, других людей, поглощает идеи. ","imageAssetId":"56077692-f208-4927-9dcd-02161a73ad84"},{"id":"skill-d8d2f316-1478-4bf7-aba1-6b1dce769113","name":"«Убер-Эго»","initial":1,"min":0,"max":10,"description":"То, что стоит выше вас. Мораль. Закон. Слово божье. То, что управляет вами. То, к чему вы стремитесь. Оно рациональное, твердое, подчиненное логике. ","imageAssetId":"32e9c875-6d43-4f81-8d07-53c017a8ae32"}],"statuses":[{"id":"status-dd5589a2-139f-43b1-8e2e-634dfb01edd2","name":"Юноша","description":"Вы Юноша. Общество относится к вам соответственно.","initiallyActive":false,"modifiers":{}},{"id":"status-e8b2a38e-a7fb-4442-b1ad-7dac4214938b","name":"Девушка","description":"Вы Девушка. Общество относится к вам соответственно.","initiallyActive":false,"modifiers":{}}]},"flags":{"awakened":false,"stul_N":null,"read":null,"good_looking":false,"bad_looking":false,"pp":true,"up_icon":false,"gone_icon":false},"scripts":[{"id":"script-0ca99cfc-4880-4b6a-9856-f8fd6c09e31b","name":"Увертюра","entryNodeId":"node-48fb3762-795a-474a-946e-4c0436f6f284","nodes":[{"id":"node-48fb3762-795a-474a-946e-4c0436f6f284","paragraphs":[{"spans":[{"text":"...","marks":[]}],"audioAssetId":"38cecc81-cc15-40aa-b1d5-8323d8dc6327","audioLoop":false,"audioVolume":0.5},{"spans":[{"text":"Пустота. Мягкая, тянущая, вязкая. Будто утопая нигде. Существуя... в ничем.","marks":["italic"]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-04a6289b-0cd9-444c-8f82-40f69be5322a","label":"Да... тут так спокойно.","nextNodeId":"node-e40d3f55-4a19-4263-be2d-ef713c41f933","condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]},{"id":"choice-1cfd1fe6-d611-4b98-ac86-8d66b48acaaa","label":"Что? Я не хочу быть нигде.","nextNodeId":"node-53782ddd-2bf4-4c1e-95fb-339ab443c997","condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-e40d3f55-4a19-4263-be2d-ef713c41f933","paragraphs":[{"spans":[{"text":"Верно... тут нет никого, и ничего, что могло бы помешать твоему спокойствию. Нет срочных дел. Нет людей, которые тебя ненавидят. И... ","marks":["italic"]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-6d64c6b4-a3f1-4e68-8e6b-e2e959aec488","label":"Нет людей, которые меня любят...","nextNodeId":"node-5a163e06-7a04-4634-82f2-7bea5b2db15d","condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-53782ddd-2bf4-4c1e-95fb-339ab443c997","paragraphs":[{"spans":[{"text":"Почему? Ты впервые за долгое время по-настоящему отдыхаешь... ","marks":["italic"]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-457377d6-d7ff-45f8-9409-44f7d46d047e","label":"От чего?","nextNodeId":"node-ff912a66-9b7b-4aa2-b8e4-e7afe739cdb7","condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-5a163e06-7a04-4634-82f2-7bea5b2db15d","paragraphs":[{"spans":[{"text":"Верно. И их тут тоже нет. ","marks":["italic"]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-59b3cf2d-199c-4528-a17d-3534fa204fc4","label":"Я хочу их увидеть.","nextNodeId":"node-58088993-ed89-4147-9508-a4231e6cf455","condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-ff912a66-9b7b-4aa2-b8e4-e7afe739cdb7","paragraphs":[{"spans":[{"text":"Ты не помнишь. И правильно делаешь. ","marks":["italic"]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-2c2ac942-72d0-401c-9760-18389968b10d","label":"Я все равно хочу обратно!","nextNodeId":"node-d0374888-967f-4981-a059-1cf6ae3222b7","condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-58088993-ed89-4147-9508-a4231e6cf455","paragraphs":[{"spans":[{"text":"...","marks":[]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-fe7058e2-fd6d-49b0-9f96-140bef16a83b","label":"Продолжить","nextNodeId":"node-0725a041-845a-455b-bc90-27290e86f885","condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions":[]}]},{"id":"node-0725a041-845a-455b-bc90-27290e86f885","paragraphs":[{"spans":[{"text":"Тогда ищи их.","marks":["italic"]}],"audioAssetId":null,"audioLoop":false,"audioVolume":1}],"choices":[{"id":"choice-ae52e396-5a31-4723-89dc-71f3fecfbdc1","label":"Продолжить","nextNodeId":null,"condition":null,"unavailableReason":"","checkId":null,"failureNodeId":null,"failureActions":[],"actions"